fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo, choose 'Testing', then click the 'Runs' tab. Then walk these sections IN ORDER, and as you arrive at each set \"checkpointReached\" to the exact checkpoint name shown: (1) runs-status-filter - the filter bar shows status chips (All, Running, Passed, Failed, Error); click 'Passed' then 'Failed', confirming the active chip highlights and the runs table plus result count respond (narrowing, or a clear 'No test runs found' empty state), then click 'All' to restore; (2) runs-search-time-range - type a term into the 'Search by test name...' box and confirm the table narrows to name matches (or shows the empty state), clear it with the X, then change the time-range dropdown (Today / This Week / This Month / Last 90 Days) and confirm the table/results respond; (3) run-detail-panel - if any run rows are present, click a run row (or its eye/View-details icon) to open a slide-in detail panel showing the test name, a metrics grid (Score, Duration, Cost, Started), an Evaluation section, and a Human Feedback area, then close it with the X or Escape (a 'No test runs found' empty state also counts). Keep going until every section has been visited. Pages can take 10-30s to load in this resource-constrained environment - wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "runs-status-filter",
      "instruction": "use the status filter chips to drive the runs table",
      "visualCriteria": [
        "The Runs view shows status filter chips (All, Running, Passed, Failed, Error); clicking a chip marks it active and updates the runs table and/or the results count, with a clear 'No test runs found' empty state when a filter matches nothing"
      ]
    },
    {
      "name": "runs-search-time-range",
      "instruction": "narrow runs by name search and change the time range",
      "visualCriteria": [
        "Typing in the 'Search by test name...' box narrows the runs table to matching names (or shows a clear empty state) and clearing it restores the list, AND changing the time-range dropdown re-queries and updates the runs table/results"
      ]
    },
    {
      "name": "run-detail-panel",
      "instruction": "open a run's slide-in detail panel and dismiss it",
      "visualCriteria": [
        "Clicking a run row opens a slide-in detail panel showing the test name plus a metrics grid (Score/Duration/Cost/Started) and an Evaluation section, and it can be dismissed - OR a valid 'No test runs found' empty state confirms there are no runs to open"
      ]
    }
  ]
}
